import{_ as a,o as i,c as n,a0 as r}from"./chunks/framework.BGyYNsHo.js";const u=JSON.parse('{"title":"Recuperación física de la abstracción del RDII ([RDII_DECAY])","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/modificaciones-motor/08-rdii-decay.md","filePath":"es/explanation/modificaciones-motor/08-rdii-decay.md"}'),t={name:"es/explanation/modificaciones-motor/08-rdii-decay.md"};function o(c,e,d,l,m,s){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="recuperacion-fisica-de-la-abstraccion-del-rdii-rdii-decay" tabindex="-1">Recuperación física de la abstracción del RDII (<code>[RDII_DECAY]</code>) <a class="header-anchor" href="#recuperacion-fisica-de-la-abstraccion-del-rdii-rdii-decay" aria-label="Permalink to &quot;Recuperación física de la abstracción del RDII (`[RDII_DECAY]`)&quot;">​</a></h1><h2 id="motivacion" tabindex="-1">Motivación <a class="header-anchor" href="#motivacion" aria-label="Permalink to &quot;Motivación&quot;">​</a></h2><p>En el SWMM oficial, la infiltración/entrada por lluvia (RDII, <em>rain-derived inflow and infiltration</em>) se modela con el método RTK: cada nodo responde con hasta tres hidrogramas unitarios triangulares (corto, medio y largo) definidos por $R$, $T$ y $K$, convolucionados con la precipitación. La abstracción inicial (capacidad de almacenamiento antes de que se genere RDII) se recupera entre eventos a <em>tasa constante</em> dada por una tabla mensual (<code>IA_Recov</code>): la variación estacional debe pre-cocinarse en los datos de entrada del usuario.</p><h2 id="la-extension-abstraccion-de-decaimiento-exponencial" tabindex="-1">La extensión: abstracción de decaimiento exponencial <a class="header-anchor" href="#la-extension-abstraccion-de-decaimiento-exponencial" aria-label="Permalink to &quot;La extensión: abstracción de decaimiento exponencial&quot;">​</a></h2><p>La extensión <code>[RDII_DECAY]</code> reemplaza esa recuperación constante por un modelo físico de <em>relajación exponencial de primer orden</em> cuya tasa depende de la <em>temperatura del aire</em>. Los parámetros por par (grupo de hidrogramas, respuesta) son $k_{\\mathrm{dep}}$, $k_0$, $k_T$, $T_{\\mathrm{ref}}$, $\\theta_{\\mathrm{rec}}$, $T_{\\mathrm{cong}}$ y, opcionalmente, un particionado lluvia/nieve.</p><p><strong>Agotamiento durante la lluvia</strong> ($k_{\\mathrm{dep}}$): la capacidad disponible se agota exponencialmente con la lámina de lluvia $\\Delta P$,</p><p>$$IA_{\\mathrm{avail}}^{+} = IA_{\\mathrm{avail}}, e^{-k_{\\mathrm{dep}},\\Delta P}, \\qquad P_{\\mathrm{net}} = \\max!\\left(0,\\ \\Delta P - \\left(IA_{\\mathrm{avail}} - IA_{\\mathrm{avail}}^{+}\\right)\\right),$$</p><p>con contabilidad másica consistente (el almacenamiento drena exactamente lo que abstrae). $k_{\\mathrm{dep}} = 0$ desactiva la abstracción.</p><p><strong>Recuperación entre eventos</strong> ($k_0$, $k_T$, $T_{\\mathrm{ref}}$): la capacidad disponible relaja hacia el máximo,</p><p>$$\\frac{d,IA_{\\mathrm{avail}}}{dt} = k_{\\mathrm{rec}}(T), \\left(IA_{\\max} - IA_{\\mathrm{avail}}\\right), \\qquad IA_{\\mathrm{avail}}^{+} = IA_{\\max} - \\left(IA_{\\max} - IA_{\\mathrm{avail}}\\right) e^{-k_{\\mathrm{rec}}(T),\\Delta t},$$</p><p>donde la tasa de recuperación depende de la temperatura con una base independiente de la temperatura (drenaje gravitacional / redistribución capilar) más un término térmico:</p><p>$$k_{\\mathrm{rec}}(T) = \\max!\\left(0,\\ k_0 + k_T, e^{\\theta_{\\mathrm{rec}},(T - T_{\\mathrm{ref}})}\\right),$$</p><p>y se anula bajo la temperatura de congelamiento $T_{\\mathrm{cong}}$ (suelo congelado), reproduciendo la elevación de RDII de inicios de primavera. La temperatura proviene de la fuente <code>[TEMPERATURE]</code> del proyecto (serie de tiempo o archivo); si no se configura, $T$ se fija en $T_{\\mathrm{ref}}$ y se emite una advertencia.</p><p><strong>Particionado lluvia/nieve (opcional)</strong>: con la cláusula <code>SNOW</code>, $T \\le T_{\\mathrm{nieve}}$ acumula la precipitación como equivalente en nieve (sin aporte líquido), y con nieve presente y $T &gt; T_{\\mathrm{nieve}}$ se agrega un derretimiento de grado-día $m = \\min!\\left(SWE,\\ DDF,(T - T_{\\mathrm{nieve}}),\\Delta t\\right)$ a la lluvia (lluvia sobre nieve).</p><p>La recuperación de primer orden es más rápida cuando el déficit es grande y se ralentiza cerca de la saturación, a diferencia de la tasa constante lineal del SWMM oficial. Los pares sin fila en <code>[RDII_DECAY]</code> usan el modelo lineal legado; el estado de ejecución (el tirante $ia_{\\mathrm{used}}$) es intercambiable entre formulaciones, por lo que los archivos de arranque en caliente son compatibles.</p>',15)])])}const _=a(t,[["render",o]]);export{u as __pageData,_ as default};
